// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;
    function setUp() public {
        address[] memory proposers = new address[](1);
        proposers[0] = address(this);
        address[] memory executors = new address[](1);
        executors[0] = address(this);
        c = new TimelockController(0, proposers, executors);
    }

    function testFuzz_property(address account) public {
        vm.assume(account != address(0));
        vm.assume(!c.hasRole(c.PROPOSER_ROLE(), account));

        vm.prank(address(this));
        c.grantRole(c.PROPOSER_ROLE(), account);

        bytes32 admin = c.getRoleAdmin(c.PROPOSER_ROLE());
        assertTrue(admin != bytes32(0));
    }
}
